tool_input.command:
python3 - <<'EOF'
import pathlib
p = pathlib.Path("<repo>/.tmp/rehash.go")
t = p.read_text()
old = '''	addrs := []string{email}
	if second != "" {
		addrs = append(addrs, second)
	}'''
new = '''	addrs := []string{email}
	if second != "" {
		addrs = append(addrs, second)
	}
	// Also derive personal addresses from the repo's own commit history
	// (committed public data), excluding bot/noreply senders.
	if out, err := exec.Command("git", "log", "--format=%ae%n%ce").Output(); err == nil {
		seen := map[string]bool{}
		for _, a := range addrs {
			seen[a] = true
		}
		for _, ln := range strings.Split(string(out), "\\n") {
			a := strings.TrimSpace(ln)
			if a == "" || seen[a] || !strings.Contains(a, "@") {
				continue
			}
			low := strings.ToLower(a)
			if strings.Contains(low, "noreply") || strings.Contains(low, "[bot]") || strings.Contains(low, "github.com") || strings.Contains(low, "anthropic.com") || strings.Contains(low, "example.") {
				continue
			}
			seen[a] = true
			addrs = append(addrs, a)
		}
	}'''
assert old in t
t = t.replace(old, new, 1)
t = t.replace('"os"\n', '"os"\n\t"os/exec"\n', 1)
p.write_text(t)
print("history-derived addresses added")
EOF
